const p=$input.first().json.body||$input.first().json;const uuid=/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
if(!uuid.test(String(p.workflowRunId||''))||!uuid.test(String(p.customerId||p.leadId||'')))throw new Error('workflowRunId and customerId/leadId must be UUIDs');
if(!Array.isArray(p.requestedItems)||p.requestedItems.length<1||p.requestedItems.length>50)throw new Error('requestedItems must contain 1..50 catalog item requests');
for(const x of p.requestedItems){if(!uuid.test(String(x.catalogItemId||''))||!Number.isInteger(x.quantity)||x.quantity<1||x.quantity>10000)throw new Error('Each requested item needs catalogItemId UUID and integer quantity 1..10000');}
return [{json:{workflowRunId:p.workflowRunId,customerId:p.customerId||null,leadId:p.leadId||null,requestedItems:p.requestedItems,requirements:String(p.requirements||'').slice(0,10000),currency:p.currency||'VND',requestedBy:p.requestedBy||null,idempotencyKey:p.workflowRunId}}];

const req=$node['Code: Validate Requirements'].json;
const c=$node['HTTP Request: Get Customer Context'].json;
const catalog=$input.first().json;
const items=catalog.items||catalog.data?.items||catalog.data||[];
if(!Array.isArray(items))throw new Error('Catalog response must be array');
const byId=new Map(items.map(i=>[i.id,i]));
const normalized=req.requestedItems.map(x=>{
  const item=byId.get(x.catalogItemId);
  if(!item)throw new Error('Unknown catalogItemId: '+x.catalogItemId);
  if(item.isActive===false||item.status==='INACTIVE')throw new Error('Catalog item is inactive: '+x.catalogItemId);
  return {catalogItemId:item.id,sku:item.sku||null,name:item.name,description:item.description||'',quantity:x.quantity,currency:item.currency||req.currency};
});
const sourceCustomer=c.data||c;
const customerContext={
  entityType:sourceCustomer.entityType||'Customer',
  companyName:sourceCustomer.companyName||null,
  companyWebsite:sourceCustomer.companyWebsite||null,
  industry:sourceCustomer.industry||null,
  jobTitle:sourceCustomer.jobTitle||null
};
const minimizedRequirements=String(req.requirements||'')
  .normalize('NFKC')
  .replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi,'[REDACTED_EMAIL]')
  .replace(/(?:\+?\d[\d .()\-]{7,}\d)/g,'[REDACTED_PHONE]')
  .replace(/\b(?:\d[ -]?){8,34}\b/g,'[REDACTED_IDENTIFIER]')
  .replace(/((?:full\s+name|customer\s+name|contact(?:\s+person)?|attendee|name|attn|họ\s+tên|tên\s+khách\s+hàng|người\s+liên\s+hệ)\s*[:=]\s*)[^\n,;.!?]{2,100}/giu,'$1[REDACTED_PERSON]')
  .replace(/((?:residential\s+address|office\s+address|shipping\s+address|address|địa\s+chỉ|nơi\s+ở)\s*[:=]?\s*)[^\n;.!?]{4,150}/giu,'$1[REDACTED_ADDRESS]')
  .replace(/\b\d{1,6}\s+[\p{L}\d.'-]+(?:\s+[\p{L}\d.'-]+){0,4}\s+(?:street|st\.?|road|rd\.?|avenue|ave\.?|lane|ln\.?|boulevard|blvd\.?)\b[^,\n;]*/giu,'[REDACTED_ADDRESS]')
  .replace(/(?:số\s+\d{1,6}\s*,?\s*)?(?:đường|phố|ngõ|hẻm)\s+[\p{L}\d .'-]{2,60}/giu,'[REDACTED_ADDRESS]')
  .replace(/\b(api[_ -]?key|access[_ -]?token|refresh[_ -]?token|password|passwd|secret|mật khẩu)\s*[:=]\s*["']?[^\s,"';]+/giu,'$1=[REDACTED_SECRET]')
  .slice(0,10000);
const prompt=`Draft a concise professional B2B quote proposal using ONLY the minimized business context, requirements, and selected catalog items. Do not invent prices, discounts, tax rates, payment terms, contract terms, delivery dates or legal commitments. The backend is the only source of truth for all prices and taxes. Return JSON only: {"title":"...","executiveSummary":"...","body":"...","lineItems":[{"catalogItemId":"...","quantity":1,"description":"..."}]}. Include only catalogItemId and quantity exactly as supplied; never add products or alter quantities.
CUSTOMER=${JSON.stringify(customerContext)}
REQUIREMENTS=${minimizedRequirements}
CATALOG=${JSON.stringify(normalized)}`;
return [{json:{...req,customerContext,catalogItems:normalized,minimizedRequirements,prompt}}];

const ai=$input.first().json||{};const p=$node['HTTP Request: Gemini Proposal Draft'].json;const ctx=$node['Code: Normalize Requirements'].json;
const t=ai.candidates?.[0]?.content?.parts?.map(x=>x.text||'').join('')||'';if(!t)throw new Error('Gemini returned no proposal draft');const clean=t.replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'').trim();const r=JSON.parse(clean);
if(typeof r.title!=='string'||typeof r.executiveSummary!=='string'||typeof r.body!=='string')throw new Error('Proposal title, executiveSummary and body are required');
const lineItems=Array.isArray(r.lineItems)?r.lineItems:ctx.catalogItems.map(x=>({catalogItemId:x.catalogItemId,quantity:x.quantity,description:x.name}));
const allowed=new Map(ctx.catalogItems.map(x=>[x.catalogItemId,x]));for(const item of lineItems){if(!allowed.has(item.catalogItemId))throw new Error('AI referenced item outside requested catalog selection');if(item.quantity!==undefined&&(!Number.isInteger(item.quantity)||item.quantity<1))throw new Error('Invalid quantity in AI draft');}
return [{json:{...ctx,proposalDraft:{title:r.title.slice(0,200),executiveSummary:r.executiveSummary.slice(0,4000),body:r.body.slice(0,15000),lineItems:ctx.catalogItems.map(x=>({catalogItemId:x.catalogItemId,quantity:x.quantity,description:x.name}))}}}];

const p=$input.first().json;const price=$node['HTTP Request: Backend Pricing Validation'].json;
if(!price||!(price.data||price).currency)throw new Error('Backend price validation response is missing currency');
const result=price.data||price;const quoteTotal=Number(result.totalAmount);if(!Number.isFinite(quoteTotal)||quoteTotal<0)throw new Error('Backend did not return a valid calculated totalAmount');
const approvalRequired=Boolean(result.approvalRequired||result.requiresApproval);
return [{json:{...p,pricingResult:result,approvalRequired,calculatedTotal:quoteTotal,currency:result.currency}}];
